/* Runtime support for code generated by recomp/lift.py.
 * Guest: 32-bit x86 (Xbox, Pentium III). Host: 64-bit, little endian.
 */
#pragma once
#include <math.h>
#include <stdint.h>
#include <string.h>
#include "x86simd.h"

typedef struct X86Context {
    uint32_t eax, ecx, edx, ebx, esp, ebp, esi, edi;
    uint32_t df;        /* direction flag (0/1); other flags never cross calls */
    uint32_t fs_base;   /* guest address of the KPCR/TIB the fs segment maps to */
    /* x87 */
    double st[8];
    uint32_t top;
    uint16_t fcw, fsw;  /* fsw keeps C0..C3 only; TOP comes from `top` */
    /* MMX / SSE */
    uint64_t mm[8];
    X128 xmm[8];
    uint32_t mxcsr;
} X86Context;

typedef void (*GuestFunc)(X86Context *c);

extern uint8_t *g_mem; /* host pointer for guest address 0 (4 GB reserved) */

/* Called for code paths the lifter could not translate. Never returns. */
void x86_unimpl(X86Context *c, uint32_t va, const char *what);
/* Indirect call/jump through the function table. */
void x86_call_indirect(X86Context *c, uint32_t va);
/* Hooks for privileged or I/O instructions. */
void x86_int(X86Context *c, uint32_t va, uint32_t vector);
uint32_t x86_in(X86Context *c, uint32_t port, int size);
void x86_out(X86Context *c, uint32_t port, uint32_t value, int size);
uint64_t x86_rdtsc(X86Context *c);
/* cpuid: the Xbox CPU (Pentium III Coppermine, MMX + SSE). EFLAGS.ID as last written by popfd. */
void x86_cpuid(uint32_t *eax, uint32_t *ebx, uint32_t *ecx, uint32_t *edx);
extern uint32_t x86_eflags_id;
/* Guest function replaced by a host implementation (recomp/hle.txt). Pops its own return address and args. */
void x86_hle(X86Context *c, uint32_t va);
void x86_hook(X86Context *c, uint32_t va);   /* entry hook for recomp/hooks.txt functions */
void ug_fncount(uint32_t va);  /* debug lifts (UG_LIFT_FNCOUNT=1): count calls per function */

/* ---- memory ---- */
static inline uint8_t RD8(uint32_t a) { return g_mem[a]; }
static inline uint16_t RD16(uint32_t a) { uint16_t v; memcpy(&v, g_mem + a, 2); return v; }
static inline uint32_t RD32(uint32_t a) { uint32_t v; memcpy(&v, g_mem + a, 4); return v; }
static inline uint64_t RD64(uint32_t a) { uint64_t v; memcpy(&v, g_mem + a, 8); return v; }
static inline float RDF32(uint32_t a) { float v; memcpy(&v, g_mem + a, 4); return v; }
static inline double RDF64(uint32_t a) { double v; memcpy(&v, g_mem + a, 8); return v; }
static inline void WR8(uint32_t a, uint8_t v) { g_mem[a] = v; }
static inline void WR16(uint32_t a, uint16_t v) { memcpy(g_mem + a, &v, 2); }
static inline void WR32(uint32_t a, uint32_t v) { memcpy(g_mem + a, &v, 4); }
static inline void WR64(uint32_t a, uint64_t v) { memcpy(g_mem + a, &v, 8); }
static inline void WRF32(uint32_t a, float v) { memcpy(g_mem + a, &v, 4); }
static inline void WRF64(uint32_t a, double v) { memcpy(g_mem + a, &v, 8); }
/* MMIO-checked accesses (emitted for the XDK D3D section). Addresses >= 0xFD000000 are NV2A/APU registers. */
uint32_t mmio_read(uint32_t a, int size);
void mmio_write(uint32_t a, uint32_t v, int size);
#define IS_MMIO(a) __builtin_expect((a) >= 0xFD000000u, 0)
static inline uint8_t RD8X(uint32_t a) { return IS_MMIO(a) ? (uint8_t)mmio_read(a, 1) : RD8(a); }
static inline uint16_t RD16X(uint32_t a) { return IS_MMIO(a) ? (uint16_t)mmio_read(a, 2) : RD16(a); }
static inline uint32_t RD32X(uint32_t a) { return IS_MMIO(a) ? mmio_read(a, 4) : RD32(a); }
static inline void WR8X(uint32_t a, uint8_t v) { if (IS_MMIO(a)) mmio_write(a, v, 1); else WR8(a, v); }
static inline void WR16X(uint32_t a, uint16_t v) { if (IS_MMIO(a)) mmio_write(a, v, 2); else WR16(a, v); }
static inline void WR32X(uint32_t a, uint32_t v) { if (IS_MMIO(a)) mmio_write(a, v, 4); else WR32(a, v); }

/* ---- flags ---- */
static inline uint8_t PARITY(uint32_t v) { return (uint8_t)(~__builtin_popcount(v & 0xFF) & 1); }

/* ---- x87 ---- */
#define ST(i) (c->st[(c->top + (i)) & 7])
static inline void FPUSH(X86Context *c, double v) { c->top = (c->top - 1) & 7; c->st[c->top] = v; }
static inline double FPOP(X86Context *c) { double v = c->st[c->top]; c->top = (c->top + 1) & 7; return v; }

/* Compare a with b and set C0/C2/C3 like fcom. */
static inline void FCOM(X86Context *c, double a, double b) {
    uint16_t s = c->fsw & ~0x4500;
    if (isnan(a) || isnan(b)) s |= 0x4500;
    else if (a < b) s |= 0x0100;
    else if (a == b) s |= 0x4000;
    c->fsw = s;
}
static inline uint16_t FSTSW(X86Context *c) { return (uint16_t)((c->fsw & ~0x3800) | ((c->top & 7) << 11)); }
/* fcomi/fucomi: ZF PF CF */
#define FCOMI(a, b) do { double _a = (a), _b = (b); \
    if (isnan(_a) || isnan(_b)) { zf = pf = cf = 1; } \
    else { zf = _a == _b; pf = 0; cf = _a < _b; } of = sf = 0; } while (0)

/* Round per the x87 control word (RC bits 10-11). */
static inline double FROUND(X86Context *c, double v) {
    switch ((c->fcw >> 10) & 3) {
    case 0: return nearbyint(v); /* host default is round-to-nearest-even */
    case 1: return floor(v);
    case 2: return ceil(v);
    default: return trunc(v);
    }
}
static inline int16_t FIST16(X86Context *c, double v) {
    v = FROUND(c, v);
    return (v >= -32768.0 && v <= 32767.0) ? (int16_t)v : (int16_t)0x8000;
}
static inline int32_t FIST32(X86Context *c, double v) {
    v = FROUND(c, v);
    return (v >= -2147483648.0 && v <= 2147483647.0) ? (int32_t)v : (int32_t)0x80000000;
}
static inline int64_t FIST64(X86Context *c, double v) {
    v = FROUND(c, v);
    return (v >= -9223372036854775808.0 && v < 9223372036854775808.0) ? (int64_t)v : INT64_MIN;
}
/* fisttp: truncate; out of range or NaN gives the x86 "integer indefinite" (a plain C cast is undefined there and
 * saturates on ARM) */
static inline int16_t FISTT16(double v) { v = trunc(v); return (v >= -32768.0 && v <= 32767.0) ? (int16_t)v : (int16_t)0x8000; }
static inline int32_t FISTT32(double v) {
    v = trunc(v);
    return (v >= -2147483648.0 && v <= 2147483647.0) ? (int32_t)v : (int32_t)0x80000000;
}
static inline int64_t FISTT64(double v) {
    v = trunc(v);
    return (v >= -9223372036854775808.0 && v < 9223372036854775808.0) ? (int64_t)v : INT64_MIN;
}
double x87_load80(uint32_t a);
void x87_store80(uint32_t a, double v);

/* ---- integer helpers ---- */
static inline uint32_t ROL32(uint32_t v, unsigned n) { n &= 31; return n ? (v << n) | (v >> (32 - n)) : v; }
static inline uint32_t ROR32(uint32_t v, unsigned n) { n &= 31; return n ? (v >> n) | (v << (32 - n)) : v; }

